package issues

import (
	"regexp"
	"strings"
)

var (
	// htmlComment is a mark se leaves in an issue, a comment or a PR: <!-- se:new -->.
	htmlComment = regexp.MustCompile(`(?s)<!--.*?-->`)
	// footer is the attribution a body ends with: a rule, then the line that
	// names what generated it, "_Generated by [Claude Code](…)_" or
	// "🤖 Generated with [Claude Code](…)", and what follows it.
	footer = regexp.MustCompile(`(?s)(?:\n[ \t]*-{3,})?\s*\n[ \t]*(?:🤖[ \t]*)?_?Generated (?:by|with) \[Claude Code\]\([^)]*\)_?(?:[ \t]*\n.*)?$`)
	// blankRun is more than one blank line in a row, which a removed mark leaves.
	blankRun = regexp.MustCompile(`\n[ \t]*\n(?:[ \t]*\n)+`)
)

// Shown is an issue's text as se prints it: without se's machine marks and
// without the attribution footer. Every text se prints of an issue, a comment
// or a PR goes through it; what se reads its marks from is the text on GitHub.
func Shown(text string) string {
	text = htmlComment.ReplaceAllString(strings.ReplaceAll(text, "\r\n", "\n"), "")
	text = footer.ReplaceAllString("\n"+text, "")
	text = blankRun.ReplaceAllString(text, "\n\n")
	lines := strings.Split(text, "\n")
	for k, l := range lines {
		lines[k] = strings.TrimRight(l, " \t")
	}
	return strings.TrimSpace(strings.Join(lines, "\n"))
}
